import java.lang.reflect.*;import java.sql.*;import java.util.*;import restaurante.dao.mysql.PedidoDAOMySQL;import restaurante.modelo.Pedido;
public class VerificaPedidos {
 static boolean error,commit,rollback,autoff;static List<String> sentencias;
 static Object def(Class<?>t){if(!t.isPrimitive())return null;if(t==boolean.class)return false;if(t==int.class)return 0;if(t==long.class)return 0L;if(t==double.class)return 0d;return null;}
 @SuppressWarnings("unchecked")static<T>T p(Class<T>t,InvocationHandler h){return(T)Proxy.newProxyInstance(t.getClassLoader(),new Class<?>[]{t},h);}
 static ResultSet fila(Object...v){int[] n={0};return p(ResultSet.class,(o,m,a)->{switch(m.getName()){case "next":return n[0]++==0;case "getInt":return ((Number)v[(Integer)a[0]-1]).intValue();case "getObject":return v[(Integer)a[0]-1];default:return def(m.getReturnType());}});}
 static Connection c(){return p(Connection.class,(o,m,a)->{switch(m.getName()){case "setAutoCommit":autoff=Boolean.FALSE.equals(a[0]);return null;case "commit":commit=true;return null;case "rollback":rollback=true;return null;case "prepareStatement":{String sql=(String)a[0];sentencias.add(sql.toLowerCase(Locale.ROOT));return p(PreparedStatement.class,(x,k,b)->{if(k.getName().equals("executeQuery")){if(sql.contains("SELECT e.id_empleado"))return fila(1,1);return fila(1);}if(k.getName().equals("getGeneratedKeys"))return fila(22);if(k.getName().equals("executeUpdate")){if(error&&(sql.startsWith("INSERT INTO detalle_pedido")||sql.startsWith("DELETE FROM detalle_pedido")))throw new SQLException("Fallo simulado de detalle");return 1;}return def(k.getReturnType());});}default:return def(m.getReturnType());}});}
 static class D implements Driver{public Connection connect(String u,Properties p){return c();}public boolean acceptsURL(String u){return u.startsWith("jdbc:mysql:");}public DriverPropertyInfo[]getPropertyInfo(String u,Properties p){return new DriverPropertyInfo[0];}public int getMajorVersion(){return 1;}public int getMinorVersion(){return 0;}public boolean jdbcCompliant(){return false;}public java.util.logging.Logger getParentLogger(){return java.util.logging.Logger.getGlobal();}}
 static void verificar(boolean eliminar,boolean falla){error=falla;commit=false;rollback=false;autoff=false;sentencias=new ArrayList<>();Pedido p=new Pedido("test");p.setIdEmpleado(1);p.setIdCliente(1);p.setIdMesa(1);p.agregarDetalle(1,"prueba",1,1);try{if(eliminar)new PedidoDAOMySQL().eliminar("test");else new PedidoDAOMySQL().guardar(p);if(falla)throw new AssertionError("Debía fallar");}catch(IllegalArgumentException ex){if(!falla)throw ex;}if(!autoff||commit==falla||rollback!=falla)throw new AssertionError("Estado incorrecto");String sql=String.join(" ",sentencias);String[] tablas=eliminar?new String[]{"pedidos","detalle_pedido","productos","pagos","pedido_eventos"}:new String[]{"pedidos","detalle_pedido","productos","empleados","clientes"};for(String t:tablas)if(!sql.contains(t))throw new AssertionError("Falta tabla "+t);if(!eliminar&&p.getIdPedido()!=(falla?0:22))throw new AssertionError("ID no coherente");System.out.println("OK: "+(eliminar?"eliminación":"registro")+(falla?" revierte al fallar":" confirma con al menos cinco tablas"));}
 public static void main(String[]a)throws Exception{Class.forName("com.mysql.cj.jdbc.Driver");for(Enumeration<Driver>d=DriverManager.getDrivers();d.hasMoreElements();)DriverManager.deregisterDriver(d.nextElement());DriverManager.registerDriver(new D());verificar(false,false);verificar(false,true);verificar(true,false);verificar(true,true);}
}
